"use client";

import type { ComponentProps } from "react";

import { Shutter } from "@/components/shutter";

/** Rectangular window shutter. Color: Industrial. */
export function ShutterRectangleIndustrial(props: ComponentProps<typeof Shutter>) {
  return (
    <Shutter
      size="md"
      defaultLevel={65}
      variant="industrial"
      label="Rectangle · Industrial"
      {...props}
    />
  );
}
